# এসএসসি সাধারণ গণিত অধ্যায় ১ (বাস্তব সংখ্যা): মৌলিক সৃজনশীল প্রশ্ন (উদ্দীপক + ক, খ, গ, ঘ)
from sqlib import rec, F
import json, os, sympy as sp
r6=sp.sqrt(6)
# যাচাই
p,q=rec(0,'','23'),rec(1,'','2'); assert p==F(23,99) and p+q==F(16,11) and p*q==F(23,81)
assert '%.18f'%(23/81)=='0.283950617283950618'[:20] or str(F(23,81))=='23/81'
d=''.join(str((23*10**k)//81%10) for k in range(1,19)); assert d=='283950617283950617'
x=(sp.sqrt(3)+sp.sqrt(2))/(sp.sqrt(3)-sp.sqrt(2)); assert sp.expand(sp.radsimp(x))==5+2*r6 and sp.expand(sp.radsimp(x+1/x))==10 and sp.expand(sp.radsimp(x**2+1/x**2))==98 and sp.expand(sp.radsimp(x**3+1/x**3))==970
s=('142857'*17)[:100]; assert s[99]=='8' and sum(map(int,s))==447
nn=sp.symbols('n'); assert all((k**3-k)%6==0 for k in range(1,50)) and all((k*k-1)%8==0 for k in range(1,50,2))
A,B=rec(2,'','35'),rec(1,'4','7'); assert A==F(233,99) and B==F(133,90) and A-B==F(289,330) and A+B==F(3793,990) and round(3793/990,3)==3.831
assert ''.join(str((289*10**k)//330%10) for k in range(1,8))=='8757575'
CQ=[
("p = 0.232323… , q = 1.222… এবং r = √5 তিনটি বাস্তব সংখ্যা।",
 ["p কে p/q আকারে (সাধারণ ভগ্নাংশে) প্রকাশ কর।","p + q এর মান আবৃত্ত দশমিকে প্রকাশ কর।","প্রমাণ কর যে, r একটি অমূলদ সংখ্যা।","p × q কে আবৃত্ত দশমিক ভগ্নাংশে প্রকাশ কর এবং আবৃত্ত অংশের অঙ্কসংখ্যা নির্ণয় কর।"],
 "ক) p = 23/99\nখ) q = 1 + 2/9 = 11/9 = 121/99 ⇒ p + q = 144/99 = 16/11 = 1.454545… (45 আবৃত্ত)\nগ) ধরি √5 = a/b (a, b সহমৌলিক)। a² = 5b² ⇒ a, 5 দ্বারা বিভাজ্য; a = 5c ⇒ b² = 5c² ⇒ b-ও 5 দ্বারা বিভাজ্য — সহমৌলিকতার বিরোধী। ∴ √5 অমূলদ।\nঘ) p × q = (23/99)(11/9) = 23/81 = 0.283950617283950617… ⇒ আবৃত্ত অংশ 283950617, অঙ্কসংখ্যা 9"),
("a = √3, b = √2 এবং x = (a + b)/(a − b)।",
 ["a² − b² এর মান নির্ণয় কর এবং ab মূলদ না অমূলদ বল।","দেখাও যে, x = 5 + 2√6 এবং x একটি অমূলদ সংখ্যা।","দেখাও যে, x + 1/x একটি মূলদ সংখ্যা।","x² + 1/x² এবং x³ + 1/x³ এর মান নির্ণয় কর।"],
 "ক) a² − b² = 3 − 2 = 1; ab = √6, যা অমূলদ।\nখ) লব ও হরকে (√3 + √2) দিয়ে গুণ করে x = (3 + 2 + 2√6)/(3 − 2) = 5 + 2√6; 2√6 অমূলদ হওয়ায় x অমূলদ।\nগ) 1/x = (√3 − √2)/(√3 + √2) = 5 − 2√6 ⇒ x + 1/x = 10, যা মূলদ।\nঘ) x² + 1/x² = 10² − 2 = 98; x³ + 1/x³ = 10³ − 3 × 10 = 970"),
("0.31 ও 0.32 দুইটি দশমিক সংখ্যা এবং 1/7 একটি সাধারণ ভগ্নাংশ।",
 ["1/7 কে দশমিক ভগ্নাংশে প্রকাশ কর।","0.31 ও 0.32 এর মধ্যে দুইটি অমূলদ সংখ্যা নির্ণয় কর।","0.31 ও 0.32 এর মধ্যে দুইটি মূলদ সংখ্যা নির্ণয় কর এবং দেখাও যে এদের মধ্যে অসংখ্য মূলদ সংখ্যা আছে।","1/7 এর দশমিক বিস্তারে দশমিক বিন্দুর পরের 100তম অঙ্ক এবং প্রথম 100টি অঙ্কের যোগফল নির্ণয় কর।"],
 "ক) 1/7 = 0.142857142857… (142857 আবৃত্ত)\nখ) যেমন 0.3101001000100001… এবং 0.3120120012000120… (অসীম ও অনাবৃত্ত দশমিক)\nগ) যেমন 0.311 ও 0.315। যেকোনো দুইটি মূলদের গড় তাদের মাঝে আরেকটি মূলদ দেয়; এভাবে বারবার গড় নিয়ে অসংখ্য মূলদ পাওয়া যায়।\nঘ) আবৃত্ত অংশে 6টি অঙ্ক; 100 = 6 × 16 + 4 ⇒ 100তম অঙ্ক = 4র্থ অঙ্ক = 8\nযোগফল = 16 × (1 + 4 + 2 + 8 + 5 + 7) + (1 + 4 + 2 + 8) = 16 × 27 + 15 = 447"),
("n যেকোনো স্বাভাবিক সংখ্যা।",
 ["প্রমাণ কর যে, n(n + 1) একটি জোড় সংখ্যা।","প্রমাণ কর যে, n² + n + 1 একটি বিজোড় সংখ্যা।","প্রমাণ কর যে, n³ − n সর্বদা 6 দ্বারা বিভাজ্য।","n বিজোড় হলে প্রমাণ কর যে, n² − 1 সংখ্যাটি 8 দ্বারা বিভাজ্য।"],
 "ক) n ও n + 1 ক্রমিক, তাই এদের একটি জোড় ⇒ গুণফল জোড়।\nখ) n² + n + 1 = n(n + 1) + 1 = জোড় + 1 ⇒ বিজোড়।\nগ) n³ − n = (n − 1)n(n + 1), তিনটি ক্রমিক সংখ্যার গুণফল; এদের একটি জোড় ও একটি 3 দ্বারা বিভাজ্য ⇒ 2 × 3 = 6 দ্বারা বিভাজ্য।\nঘ) n = 2k + 1 ⇒ n² − 1 = 4k² + 4k = 4k(k + 1); k(k + 1) জোড় ⇒ n² − 1, 8 দ্বারা বিভাজ্য।"),
("A = 2.353535… এবং B = 1.4777… (শুধু 7 আবৃত্ত) দুইটি আবৃত্ত দশমিক সংখ্যা।",
 ["A কে সাধারণ ভগ্নাংশে প্রকাশ কর।","B কে সাধারণ ভগ্নাংশে প্রকাশ কর।","A − B এর মান আবৃত্ত দশমিকে প্রকাশ কর।","A + B এর মান নির্ণয় কর এবং তিন দশমিক স্থান পর্যন্ত ও তিন তাৎপর্যপূর্ণ অঙ্ক পর্যন্ত আসন্ন মান লেখ।"],
 "ক) A = 2 + 35/99 = 233/99\nখ) B = (147 − 14)/90 = 133/90\nগ) A − B = 233/99 − 133/90 = (2330 − 1463)/990 = 867/990 = 289/330 = 0.8757575… (75 আবৃত্ত)\nঘ) A + B = (2330 + 1463)/990 = 3793/990 = 3.8313131…\nতিন দশমিক স্থান পর্যন্ত 3.831; তিন তাৎপর্যপূর্ণ অঙ্ক পর্যন্ত 3.83"),
]
items=[{'n':f'b{i+1}','stem':s_,'p':p_,'a':a_,'lv':'কঠিন'} for i,(s_,p_,a_) in enumerate(CQ)]
